assertion.value:
(() => {
  const matches = String(output).match(/\[\[choices:[\s\S]*?\]\]/g) || [];
  if (matches.length !== 1) return false;
  const items = matches[0].slice(10, -2).split('|').map(x => x.trim());
  return items.length >= 2 && items.length <= 3 &&
    new Set(items).size === items.length &&
    items.every(x => x.length > 0 && x.length <= 30);
})()

